"use client";

/** Landing hero instrument: real specimen shapes, shown either as
 *  orthographic working drawings or as the actual STL this engine produced.
 *
 *  Every solid here was generated by the deployed CadQuery pipeline and is
 *  bundled in `public/specimens`, so the "Solid" view needs no backend, no
 *  account and no cold start — it is the same bytes a download would give.
 *  Demo content only; every specimen is labelled as such.
 */
import { useState, type ReactNode } from "react";
import { SpecimenModel } from "./SpecimenModel";

interface Specimen {
  key: string;
  tab: string;
  name: string;
  serial: string;
  operation: string;
  prompt: string;
  dims: [string, string, string];
  feature: string;
  files: [string, string];
  /** Bundled STL (public/, generated by the real engine). */
  model: string;
}

const SPECIMENS: Specimen[] = [
  {
    key: "plate",
    tab: "Plate",
    name: "Mounting plate, 8-hole grid",
    serial: "SP-041",
    operation: "part → hole_grid",
    prompt:
      "A 100 by 60 by 8 mm mounting plate with eight Ø5 through-holes on a 28 by 36 mm grid.",
    dims: ["100.0", "60.0", "8.0"],
    feature: "Ø5.0 × 8",
    files: ["mounting_plate.step", "mounting_plate.stl"],
    model: "/specimens/plate.stl",
  },
  {
    key: "enclosure",
    tab: "Enclosure",
    name: "Open-top enclosure",
    serial: "SP-118",
    operation: "part → shell",
    prompt:
      "An enclosure shell, 120 by 80 by 40 mm, 2.5 mm walls, open top.",
    dims: ["120.0", "80.0", "40.0"],
    feature: "2.5 wall",
    files: ["enclosure.step", "enclosure.stl"],
    model: "/specimens/enclosure.stl",
  },
  {
    key: "shaft",
    tab: "Shaft",
    name: "Shaft, through-bore",
    serial: "SP-207",
    operation: "cut",
    prompt: "A 120 mm shaft, Ø30, with a Ø15 hole through the center.",
    dims: ["30.0", "30.0", "120.0"],
    feature: "Ø15.0 through",
    files: ["shaft.step", "shaft.stl"],
    model: "/specimens/shaft.stl",
  },
];

