const DRAWINGS: Record<string, () => ReactNode> = {
  plate: PlateDrawing,
  enclosure: EnclosureDrawing,
  shaft: ShaftDrawing,
};

export function SpecimenPanel() {
  const [active, setActive] = useState(0);
  const [solid, setSolid] = useState(false);
  const [solidUnavailable, setSolidUnavailable] = useState(false);
  const specimen = SPECIMENS[active];
  const Drawing = DRAWINGS[specimen.key];
  const showSolid = solid && !solidUnavailable;

  return (
    <div className="lp-inst">
      <div className="lp-inst-bar mono">
        <span>specimen {String(active + 1).padStart(2, "0")} / 03</span>
        <span className="lp-live">
          <i aria-hidden="true" /> validated
        </span>
      </div>

      <div className="lp-inst-tabs" role="tablist" aria-label="Example specimens">
        {SPECIMENS.map((item, index) => (
          <button
            key={item.key}
            type="button"
            role="tab"
            id={`specimen-tab-${item.key}`}
            aria-selected={index === active}
            aria-controls="specimen-panel"
            className="lp-inst-tab"
            onClick={() => setActive(index)}
          >
            <span className="mono">{String(index + 1).padStart(2, "0")}</span>
            {item.tab}
          </button>
        ))}
      </div>

      <div
        className="lp-inst-well"
        id="specimen-panel"
        role="tabpanel"
        aria-labelledby={`specimen-tab-${specimen.key}`}
        aria-live="polite"
      >
        <div className="lp-inst-well-tag mono">
          <span>{specimen.serial}</span>
          <span>{showSolid ? "SOLID · STL" : "SECTION A–A"}</span>
        </div>

        <div className="lp-inst-mode" role="group" aria-label="Specimen view">
          <button
            type="button"
            className="lp-inst-mode-btn mono"
            aria-pressed={!showSolid}
            onClick={() => setSolid(false)}
          >
            Drawing
          </button>
          <button
            type="button"
            className="lp-inst-mode-btn mono"
            aria-pressed={showSolid}
            disabled={solidUnavailable}
            title={
              solidUnavailable ? "3D is unavailable on this device" : undefined
            }
            onClick={() => setSolid(true)}
          >
            Solid
          </button>
        </div>

        {showSolid ? (
          <SpecimenModel
            url={specimen.model}
            label={`${specimen.serial} · ${specimen.name}`}
            onFail={() => setSolidUnavailable(true)}
          />
        ) : (
          <Drawing />
        )}
        {solidUnavailable && solid ? (
          <p className="lp-inst-solid-fallback mono" role="status">
            3D unavailable on this device — showing the working drawing.
          </p>
        ) : null}
        <p className="lp-inst-prompt">{specimen.prompt}</p>
      </div>

      <dl className="lp-inst-dro">
        {(["X", "Y", "Z"] as const).map((axis, index) => (
          <div key={axis} className="lp-dro-row">
            <dt className="mono">{axis}</dt>
            <dd className="mono">
              {specimen.dims[index]}
              <span>mm</span>
            </dd>
          </div>
        ))}
        <div className="lp-dro-row lp-dro-wide">
          <dt className="mono">feature</dt>
          <dd className="mono">{specimen.feature}</dd>
        </div>
        <div className="lp-dro-row lp-dro-wide">
          <dt className="mono">operation</dt>
          <dd className="mono">{specimen.operation}</dd>
        </div>
      </dl>

      <div className="lp-inst-foot mono">
        <span>{specimen.name}</span>
        <span>
          {specimen.files[0]} · {specimen.files[1]}
        </span>
      </div>
      <p className="lp-inst-note mono">
        Example specimen, not a customer file · solid generated by this engine
      </p>
    </div>
  );
}
